create table public.threads (id uuid primary key default gen_random_uuid(), user_id uuid not null, title text not null default 'Nova conversa', created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create table public.messages (id uuid primary key default gen_random_uuid(), thread_id uuid not null references public.threads(id) on delete cascade, role text not null, parts jsonb not null default '[]'::jsonb, created_at timestamptz not null default now()); create index messages_thread_id_idx on public.messages(thread_id, created_at); grant select, insert, update, delete on public.threads to authenticated; grant select, insert, update, delete on public.messages to authenticated; grant all on public.threads to service_role; grant all on public.messages to service_role; alter table public.threads enable row level security; alter table public.messages enable row level security; create policy threads_owner_select on public.threads for select to authenticated using (auth.uid() = user_id); create policy threads_owner_insert on public.threads for insert to authenticated with check (auth.uid() = user_id); create policy threads_owner_update on public.threads for update to authenticated using (auth.uid() = user_id); create policy threads_owner_delete on public.threads for delete to authenticated using (auth.uid() = user_id); create policy messages_owner_select on public.messages for select to authenticated using (exists (select 1 from public.threads t where t.id = thread_id and t.user_id = auth.uid())); create policy messages_owner_insert on public.messages for insert to authenticated with check (exists (select 1 from public.threads t where t.id = thread_id and t.user_id = auth.uid())); create policy messages_owner_delete on public.messages for delete to authenticated using (exists (select 1 from public.threads t where t.id = thread_id and t.user_id = auth.uid()));